import sys

MOD = 998244353
G = 3

def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for i in range(0, n, length):
            w = 1
            end = i + half
            for p in range(i, end):
                u = a[p]
                v = a[p + half] * w % MOD
                a[p] = (u + v) % MOD
                a[p + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD

def convolution(a, b):
    if not a or not b:
        return []
    need = len(a) + len(b) - 1
    if min(len(a), len(b)) <= 40:
        res = [0] * need
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    res[i + j] = (res[i + j] + x * y) % MOD
        return res

    n = 1
    while n < need:
        n <<= 1
    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    ntt(fa, False)
    ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:need]

def main():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()
    M = 2 * N

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    ifact = [1] * (N + 1)
    ifact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        ifact[i - 1] = ifact[i] * i % MOD

    wp = [0] * (M + 1)
    bp = [0] * (M + 1)
    for i, ch in enumerate(S, 1):
        wp[i] = wp[i - 1] + (ch == 'W')
        bp[i] = bp[i - 1] + (ch == 'B')

    h = [0] * (M + 1)
    add = [0] * (M + 1)
    h[0] = 1

    DIRECT_LIMIT = 2500

    def propagate_direct(l, mid, r):
        for j in range(l, mid):
            val = h[j]
            if val == 0:
                continue
            a = wp[j]
            b = bp[j]
            if a >= b:
                base = val * ifact[a - b] % MOD
                for i in range(mid, r):
                    k = wp[i]
                    if b <= k:
                        add[i] = (add[i] + base * fact[k - b]) % MOD
            else:
                base = val * fact[b - a - 1] % MOD
                if a & 1:
                    base = (-base) % MOD
                for i in range(mid, r):
                    k = wp[i]
                    if k < b:
                        term = base * ifact[b - k - 1] % MOD
                        if k & 1:
                            term = (-term) % MOD
                        add[i] += term
                        if add[i] >= MOD:
                            add[i] -= MOD

    def propagate_ntt(l, mid, r):
        # Type 1:
        # a >= b:
        # h[j] * (k-b)! / (a-b)!
        max_k = max(wp[mid:r])
        sources = []
        min_b = N + 1
        for j in range(l, mid):
            a = wp[j]
            b = bp[j]
            if a >= b and b <= max_k and h[j]:
                sources.append((b, h[j] * ifact[a - b] % MOD))
                if b < min_b:
                    min_b = b

        if sources:
            width = max_k - min_b
            arr = [0] * (width + 1)
            for b, v in sources:
                pos = b - min_b
                arr[pos] += v
                if arr[pos] >= MOD:
                    arr[pos] -= MOD
            ker = fact[:width + 1]
            conv = convolution(arr, ker)
            for i in range(mid, r):
                idx = wp[i] - min_b
                if 0 <= idx < len(conv):
                    add[i] += conv[idx]
                    if add[i] >= MOD:
                        add[i] -= MOD

        # Type 2:
        # a < b and k < b:
        # h[j] * (-1)^(k-a) * (b-a-1)! / (b-k-1)!
        min_k = min(wp[mid:r])
        sources = []
        max_b = -1
        for j in range(l, mid):
            a = wp[j]
            b = bp[j]
            if a < b and b > min_k and h[j]:
                v = h[j] * fact[b - a - 1] % MOD
                if a & 1:
                    v = (-v) % MOD
                sources.append((b, v))
                if b > max_b:
                    max_b = b

        if sources:
            width = max_b - min_k - 1
            arr = [0] * (width + 1)
            for b, v in sources:
                arr[max_b - b] += v
                if arr[max_b - b] >= MOD:
                    arr[max_b - b] -= MOD
            ker = ifact[:width + 1]
            conv = convolution(arr, ker)
            for i in range(mid, r):
                idx = max_b - wp[i] - 1
                if 0 <= idx < len(conv):
                    v = conv[idx]
                    if wp[i] & 1:
                        v = (-v) % MOD
                    add[i] += v
                    if add[i] >= MOD:
                        add[i] -= MOD

    sys.setrecursionlimit(1 << 20)

    def cdq(l, r):
        if r - l == 1:
            if l != 0:
                h[l] = (-add[l]) % MOD
            return

        mid = (l + r) >> 1
        cdq(l, mid)

        if (mid - l) * (r - mid) <= DIRECT_LIMIT:
            propagate_direct(l, mid, r)
        else:
            propagate_ntt(l, mid, r)

        cdq(mid, r)

    cdq(0, M + 1)
    print((-h[M]) % MOD)

if __name__ == "__main__":
    main()

import sys

sys.setrecursionlimit(1_000_000)

def solve():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())

    A = [0] * M
    B = [0] * M
    for i in range(M):
        s, t = map(int, input().split())
        if s > t:
            s, t = t, s
        A[i] = s
        B[i] = t

    size = 1
    while size <= N:
        size <<= 1

    best1 = [0] * (size << 1)
    best2 = [0] * (size << 1)
    stamp = [0] * (size << 1)
    token = 0

    prev_bad = [0] * M

    def add_point(pos, idx, tok):
        p = pos + size - 1
        while p:
            if stamp[p] != tok:
                stamp[p] = tok
                best1[p] = idx
                best2[p] = 0
            else:
                x = best1[p]
                if idx > x:
                    best2[p] = x
                    best1[p] = idx
                elif idx > best2[p]:
                    best2[p] = idx
            p >>= 1

    def query_range(left, right, tok):
        if left > right:
            return 0, 0
        left += size - 1
        right += size - 1
        x1 = 0
        x2 = 0

        while left <= right:
            if left & 1:
                if stamp[left] == tok:
                    v1 = best1[left]
                    v2 = best2[left]
                    if v1 > x1:
                        if x1 > x2:
                            x2 = x1
                        x1 = v1
                    elif v1 > x2:
                        x2 = v1
                    if v2 > x1:
                        if x1 > x2:
                            x2 = x1
                        x1 = v2
                    elif v2 > x2:
                        x2 = v2
                left += 1
            if not (right & 1):
                if stamp[right] == tok:
                    v1 = best1[right]
                    v2 = best2[right]
                    if v1 > x1:
                        if x1 > x2:
                            x2 = x1
                        x1 = v1
                    elif v1 > x2:
                        x2 = v1
                    if v2 > x1:
                        if x1 > x2:
                            x2 = x1
                        x1 = v2
                    elif v2 > x2:
                        x2 = v2
                right -= 1
            left >>= 1
            right >>= 1

        return x1, x2

    def update_answer(cur, p1, p2):
        ans = prev_bad[cur]
        if p1:
            j = p1 - 1
            if A[j] != A[cur] or B[j] != B[cur]:
                if p1 > ans:
                    ans = p1
            elif p2:
                j = p2 - 1
                if A[j] != A[cur] or B[j] != B[cur]:
                    if p2 > ans:
                        ans = p2
        prev_bad[cur] = ans

    def merge_by_a(x, y):
        res = []
        i = j = 0
        lx = len(x)
        ly = len(y)
        while i < lx and j < ly:
            if A[x[i]] <= A[y[j]]:
                res.append(x[i])
                i += 1
            else:
                res.append(y[j])
                j += 1
        if i < lx:
            res.extend(x[i:])
        if j < ly:
            res.extend(y[j:])
        return res

    def merge_by_b_desc(x, y):
        res = []
        i = j = 0
        lx = len(x)
        ly = len(y)
        while i < lx and j < ly:
            if B[x[i]] >= B[y[j]]:
                res.append(x[i])
                i += 1
            else:
                res.append(y[j])
                j += 1
        if i < lx:
            res.extend(x[i:])
        if j < ly:
            res.extend(y[j:])
        return res

    def divide(lo, hi):
        nonlocal token
        if hi - lo == 1:
            return [lo], [lo]

        mid = (lo + hi) >> 1
        left_a, left_b = divide(lo, mid)
        right_a, right_b = divide(mid, hi)

        # Conflict type:
        # previous: a <= l < b <= r
        token += 1
        tok = token
        p = 0
        ln = len(left_a)

        for cur in right_a:
            l = A[cur]
            r = B[cur]
            while p < ln and A[left_a[p]] <= l:
                j = left_a[p]
                add_point(B[j], j + 1, tok)
                p += 1
            q1, q2 = query_range(l + 1, r, tok)
            update_answer(cur, q1, q2)

        # Conflict type:
        # previous: l <= a < r <= b
        token += 1
        tok = token
        p = 0
        ln = len(left_b)

        for cur in right_b:
            l = A[cur]
            r = B[cur]
            while p < ln and B[left_b[p]] >= r:
                j = left_b[p]
                add_point(A[j], j + 1, tok)
                p += 1
            q1, q2 = query_range(l, r - 1, tok)
            update_answer(cur, q1, q2)

        return merge_by_a(left_a, right_a), merge_by_b_desc(left_b, right_b)

    divide(0, M)

    segsize = 1
    while segsize < M:
        segsize <<= 1
    seg = [0] * (segsize << 1)

    for i in range(M):
        seg[segsize + i] = prev_bad[i]
    for i in range(segsize - 1, 0, -1):
        x = seg[i << 1]
        y = seg[i << 1 | 1]
        seg[i] = x if x >= y else y

    def range_max(l, r):
        l += segsize
        r += segsize
        ans = 0
        while l <= r:
            if l & 1:
                if seg[l] > ans:
                    ans = seg[l]
                l += 1
            if not (r & 1):
                if seg[r] > ans:
                    ans = seg[r]
                r -= 1
            l >>= 1
            r >>= 1
        return ans

    out = []
    for _ in range(Q):
        l, r = map(int, input().split())
        mx = range_max(l - 1, r - 1)
        if mx >= l:
            out.append("No")
        else:
            out.append("Yes")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

import sys
from math import isqrt
from bisect import bisect_right

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    q = data[0]
    queries = data[1:]

    limit = isqrt(max(queries))

    is_prime = bytearray(b'\x01') * (limit + 1)
    if limit >= 0:
        is_prime[0] = 0
    if limit >= 1:
        is_prime[1] = 0

    for i in range(2, isqrt(limit) + 1):
        if is_prime[i]:
            start = i * i
            is_prime[start:limit + 1:i] = b'\x00' * (((limit - start) // i) + 1)

    omega = bytearray(limit + 1)
    for p in range(2, limit + 1):
        if is_prime[p]:
            for multiple in range(p, limit + 1, p):
                omega[multiple] += 1

    numbers = []
    for m in range(2, limit + 1):
        if omega[m] == 2:
            numbers.append(m * m)

    out = []
    for a in queries:
        out.append(str(numbers[bisect_right(numbers, a) - 1]))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

import sys

def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    T = next(it)
    ans_list = []

    for _ in range(T):
        N = next(it)
        K = next(it)

        vals = []
        best_val = [0] * N
        best_col = [0] * N

        for i in range(N):
            x = next(it)
            y = next(it)
            z = next(it)
            a = (x, y, z)
            vals.append(a)
            m = max(a)
            best_val[i] = m
            if x == m:
                best_col[i] = 0
            elif y == m:
                best_col[i] = 1
            else:
                best_col[i] = 2

        chosen_count = 2 * K
        order = sorted(range(N), key=lambda i: best_val[i], reverse=True)
        selected = order[:chosen_count]
        outside = order[chosen_count:]

        base = sum(best_val[i] for i in selected)

        base_parity = 0
        sources = [[] for _ in range(3)]
        for i in selected:
            c = best_col[i]
            base_parity ^= 1 << c
            sources[c].append(i)

        if base_parity == 0:
            ans_list.append(str(base))
            continue

        for c in range(3):
            sources[c].sort(key=lambda i: best_val[i])

        outsiders_by_dim = [[] for _ in range(3)]
        for d in range(3):
            outsiders_by_dim[d] = sorted(
                outside, key=lambda i, d=d: vals[i][d], reverse=True
            )[:4]

        groups = {1: [], 2: [], 4: []}

        # Change the designated dimension of a selected cake.
        for c in range(3):
            srcs = sources[c]
            if not srcs:
                continue
            for d in range(3):
                if c == d:
                    continue
                cand = [(best_val[s] - vals[s][d], s) for s in srcs]
                cand.sort()
                parity = (1 << c) ^ (1 << d)
                for loss, s in cand[:4]:
                    groups[parity].append((loss, s, -1))

        # Replace a selected cake with an unselected cake,
        # assigning the new cake to dimension d.
        for c in range(3):
            srcs = sources[c][:4]
            if not srcs:
                continue
            for d in range(3):
                if c == d:
                    continue
                outs = outsiders_by_dim[d]
                if not outs:
                    continue
                parity = (1 << c) ^ (1 << d)
                for s in srcs:
                    ms = best_val[s]
                    for o in outs:
                        groups[parity].append((ms - vals[o][d], s, o))

        best_loss = min(x[0] for x in groups[base_parity])

        other = [p for p in (1, 2, 4) if p != base_parity]
        p, q = other[0], other[1]

        for loss1, s1, o1 in groups[p]:
            for loss2, s2, o2 in groups[q]:
                if s1 == s2:
                    continue
                if o1 != -1 and o2 != -1 and o1 == o2:
                    continue
                total_loss = loss1 + loss2
                if total_loss < best_loss:
                    best_loss = total_loss

        ans_list.append(str(base - best_loss))

    print("\n".join(ans_list))

if __name__ == "__main__":
    solve()

import sys

def solve():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()
    T = input().strip()

    to = [-1] * 26

    for a, b in zip(S, T):
        x = ord(a) - 97
        y = ord(b) - 97
        if to[x] != -1 and to[x] != y:
            print(-1)
            return
        to[x] = y

    edges = sum(1 for i in range(26) if to[i] != -1 and to[i] != i)

    state = [0] * 26
    cycles = []

    for start in range(26):
        if state[start] != 0 or to[start] == -1:
            continue

        path = []
        pos = {}
        v = start

        while v != -1 and state[v] == 0:
            state[v] = 1
            pos[v] = len(path)
            path.append(v)
            v = to[v]

        if v != -1 and state[v] == 1 and v in pos:
            cyc = path[pos[v]:]
            if len(cyc) > 1:
                cycles.append(cyc)

        for u in path:
            state[u] = 2

    is_permutation = all(x != -1 for x in to) and len(set(to)) == 26

    if is_permutation and cycles:
        print(-1)
        return

    cycles_with_feeder = 0

    for cyc in cycles:
        in_cycle = [False] * 26
        for v in cyc:
            in_cycle[v] = True

        has_feeder = False
        for u in range(26):
            if not in_cycle[u] and to[u] != -1 and in_cycle[to[u]]:
                has_feeder = True
                break

        if has_feeder:
            cycles_with_feeder += 1

    answer = edges + len(cycles) - cycles_with_feeder
    print(answer)

if __name__ == "__main__":
    solve()

import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, K = data[0], data[1]
    A = data[2:]

    comb = [1] * (K + 1)
    for j in range(1, K + 1):
        comb[j] = comb[j - 1] * (K - j + 1) // j

    power_sums = [0] * (K + 1)
    power_sums[0] = 1  # prefix sum 0

    prefix = 0
    ans = 0

    for a in A:
        prefix = (prefix + a) % MOD

        powers = [1] * (K + 1)
        for i in range(1, K + 1):
            powers[i] = powers[i - 1] * prefix % MOD

        for j in range(K + 1):
            term = comb[j] * powers[K - j] % MOD * power_sums[j] % MOD
            if j % 2 == 0:
                ans += term
            else:
                ans -= term

        ans %= MOD

        for j in range(K + 1):
            power_sums[j] = (power_sums[j] + powers[j]) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def required_divisions_upto(n: int) -> int:
            total = 0
            start = 1
            steps = 1

            while start <= n:
                end = min(n, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1

            return total

        answer = 0

        for l, r in queries:
            total_divisions = required_divisions_upto(r) - required_divisions_upto(l - 1)
            answer += (total_divisions + 1) // 2

        return answer

import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    R = int(data[1])
    C = int(data[2])
    S = data[3]

    r = c = 0
    seen = {(0, 0)}
    ans = []

    for ch in S:
        if ch == ord('N'):
            r -= 1
        elif ch == ord('S'):
            r += 1
        elif ch == ord('W'):
            c -= 1
        else:  # E
            c += 1

        seen.add((r, c))
        if (r - R, c - C) in seen:
            ans.append('1')
        else:
            ans.append('0')

    print(''.join(ans))

if __name__ == "__main__":
    main()

import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    graph = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        graph[u].append(v)
        graph[v].append(u)

    color = [-1] * N
    has_odd_component = False
    parity_of_one_side_sum = 0

    for start in range(N):
        if color[start] != -1:
            continue

        color[start] = 0
        q = deque([start])
        cnt = [1, 0]

        while q:
            v = q.popleft()
            for to in graph[v]:
                if color[to] == -1:
                    color[to] = color[v] ^ 1
                    cnt[color[to]] += 1
                    q.append(to)

        if (cnt[0] + cnt[1]) % 2 == 1:
            has_odd_component = True

        parity_of_one_side_sum ^= (cnt[0] & 1)

    if N % 2 == 1:
        first_wins = (M % 2 == 1)
    elif has_odd_component:
        first_wins = True
    else:
        first_wins = ((M & 1) != parity_of_one_side_sum)

    print("Aoki" if first_wins else "Takahashi")

if __name__ == "__main__":
    main()

from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_without_zero(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            length = len(digits)

            result = sum(9 ** k for k in range(1, length))

            for i, digit in enumerate(digits):
                remaining = length - i - 1
                if digit == 0:
                    return result

                result += (digit - 1) * (9 ** remaining)

            return result + 1

        def count_beautiful_up_to(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            length = len(digits)

            # Every number containing a zero digit is automatically beautiful.
            no_zero_count = count_without_zero(n)
            answer = n - no_zero_count

            # Count beautiful numbers whose digits are all non-zero.
            for target_sum in range(1, 9 * length + 1):
                @lru_cache(None)
                def dp(pos: int, remaining_sum: int, product_mod: int,
                       started: int, tight: int) -> int:
                    remaining_positions = length - pos

                    if remaining_sum < 0 or remaining_sum > 9 * remaining_positions:
                        return 0

                    if started and remaining_sum < remaining_positions:
                        return 0

                    if pos == length:
                        return int(started and remaining_sum == 0 and product_mod == 0)

                    limit = digits[pos] if tight else 9
                    total = 0

                    if not started:
                        # Keep skipping leading positions.
                        total += dp(
                            pos + 1,
                            remaining_sum,
                            product_mod,
                            0,
                            int(tight and limit == 0)
                        )

                        for digit in range(1, limit + 1):
                            if digit <= remaining_sum:
                                total += dp(
                                    pos + 1,
                                    remaining_sum - digit,
                                    (product_mod * digit) % target_sum,
                                    1,
                                    int(tight and digit == limit)
                                )
                    else:
                        for digit in range(1, limit + 1):
                            if digit <= remaining_sum:
                                total += dp(
                                    pos + 1,
                                    remaining_sum - digit,
                                    (product_mod * digit) % target_sum,
                                    1,
                                    int(tight and digit == limit)
                                )

                    return total

                answer += dp(0, target_sum, 1 % target_sum, 0, 1)

            return answer

        return count_beautiful_up_to(r) - count_beautiful_up_to(l - 1)

from typing import List


class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]
        max_depth = 0

        for word in words:
            node = 0
            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                count[node] += 1
            max_depth = max(max_depth, len(word))

        freq = [0] * (max_depth + 1)
        for node in range(1, len(children)):
            if count[node] >= k:
                freq[depth[node]] += 1

        size = 1
        while size <= max_depth:
            size <<= 1

        seg = [0] * (2 * size)
        for d in range(1, max_depth + 1):
            if freq[d] > 0:
                seg[size + d] = d

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[i << 1], seg[i << 1 | 1])

        def update(d: int, delta: int) -> None:
            freq[d] += delta
            pos = size + d
            seg[pos] = d if freq[d] > 0 else 0
            pos >>= 1
            while pos:
                new_val = max(seg[pos << 1], seg[pos << 1 | 1])
                if seg[pos] == new_val:
                    break
                seg[pos] = new_val
                pos >>= 1

        answer = []

        for word in words:
            node = 0
            removed_depths = []

            for ch in word:
                node = children[node][ch]
                if count[node] == k:
                    d = depth[node]
                    update(d, -1)
                    removed_depths.append(d)

            answer.append(seg[1])

            for d in removed_depths:
                update(d, 1)

        return answer

