sys.setrecursionlimit(10000)

class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def max_flow(self, s, t, limit):
        flow = 0
        n = self.n

        while flow < limit:
            level = [-1] * n
            level[s] = 0
            q = deque([s])

            while q:
                v = q.popleft()
                for to, cap, _ in self.g[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        q.append(to)

            if level[t] < 0:
                break

            it = [0] * n

            def dfs(v, f):
                if v == t:
                    return f
                while it[v] < len(self.g[v]):
                    e = self.g[v][it[v]]
                    to, cap, rev = e
                    if cap > 0 and level[v] < level[to]:
                        pushed = dfs(to, min(f, cap))
                        if pushed:
                            e[1] -= pushed
                            self.g[to][rev][1] += pushed
                            return pushed
                    it[v] += 1
                return 0

            while flow < limit:
                pushed = dfs(s, limit - flow)
                if pushed == 0:
                    break
                flow += pushed

        return flow


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, k = data[0], data[1], data[2]

    edges = []
    pos = 3
    for _ in range(m):
        u = data[pos] - 1
        v = data[pos + 1] - 1
        pos += 2
        edges.append((u, v))

    INF = 10**9
    answer = 0

    for d in range(1, n):
        def node(v, level):
            return v * d + (level - 1)

        total_nodes = n * d + 2
        source = n * d
        sink = source + 1
        mf = Dinic(total_nodes)

        # Vertex 1 has label 0.
        for level in range(1, d + 1):
            mf.add_edge(node(0, level), sink, INF)

        # Vertex N has label d.
        for level in range(1, d + 1):
            mf.add_edge(source, node(n - 1, level), INF)

        # Monotonicity: [label >= i+1] implies [label >= i].
        for v in range(n):
            for level in range(2, d + 1):
                mf.add_edge(node(v, level), node(v, level - 1), INF)

        for u, v in edges:
            for level in range(1, d + 1):
                # Cost 1 if label(v) >= level but label(u) < level.
                mf.add_edge(node(v, level), node(u, level), 1)

            # label(v) <= label(u) + 1
            for level in range(2, d + 1):
                mf.add_edge(node(v, level), node(u, level - 1), INF)

        if mf.max_flow(source, sink, k + 1) <= k:
            answer = d

    print(answer)

