class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_right = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        gains = [0] * m

        max_left = 0
        second_left = 0
        max_count = 0
        max_id = -1

        total = 0

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                if left > max_left:
                    second_left = max_left
                    max_left = left
                    max_count = 1
                    max_id = idx
                elif left == max_left:
                    max_count += 1
                elif left > second_left:
                    second_left = left

            total += right - max_left

            if max_count == 1:
                gains[max_id] += max_left - second_left

        return total + max(gains)

