class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1

        ans = ['a'] * length
        fixed = [False] * length

        # Apply all mandatory 'T' constraints.
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if fixed[pos] and ans[pos] != str2[j]:
                        return ""
                    ans[pos] = str2[j]
                    fixed[pos] = True

        # Positions that are still available to alter.
        available = [not fixed[i] for i in range(length)]

        # Ensure every 'F' window differs from str2.
        for i in range(n):
            if str1[i] != 'F':
                continue

            matches = True
            for j in range(m):
                if ans[i + j] != str2[j]:
                    matches = False
                    break

            if not matches:
                continue

            # Change the rightmost still-available character.
            changed = False
            for j in range(m - 1, -1, -1):
                pos = i + j
                if available[pos]:
                    # Since the window currently matches and available
                    # characters are initially 'a', str2[j] must be 'a'.
                    ans[pos] = 'b' if str2[j] == 'a' else 'a'
                    available[pos] = False
                    changed = True
                    break

            if not changed:
                return ""

        # Safety verification of all constraints.
        for i in range(n):
            matches = True
            for j in range(m):
                if ans[i + j] != str2[j]:
                    matches = False
                    break

            if str1[i] == 'T' and not matches:
                return ""
            if str1[i] == 'F' and matches:
                return ""

        return ''.join(ans)

