class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side

        def position(x: int, y: int) -> int:
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        pos = sorted(position(x, y) for x, y in points)
        n = len(pos)
        doubled = pos + [x + perimeter for x in pos]
        m = 2 * n

        def feasible(dist: int) -> bool:
            nxt = [m] * (m + 1)
            j = 0

            for i in range(m):
                if j <= i:
                    j = i + 1
                target = doubled[i] + dist
                while j < m and doubled[j] < target:
                    j += 1
                nxt[i] = j

            steps = k - 1
            limit_offset = perimeter - dist

            for start in range(n):
                cur = start
                for _ in range(steps):
                    cur = nxt[cur]
                    if cur == m:
                        break

                if cur < m and doubled[cur] <= doubled[start] + limit_offset:
                    return True

            return False

        lo, hi = 0, side + 1
        while lo + 1 < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid

        return lo

