def solve():
    input = sys.stdin.buffer.readline
    N = int(input())

    adj = [[] for _ in range(N)]
    for i in range(N - 1):
        a, b = map(int, input().split())
        a -= 1
        b -= 1
        s = 2 * i
        adj[a].append((b, s))
        adj[b].append((a, s ^ 1))

    if N < 5:
        print(-1)
        return

    parent = [-1] * N
    parent_slot = [-1] * N
    parent[0] = 0
    order = []
    stack = [0]

    while stack:
        v = stack.pop()
        order.append(v)
        for to, slot in adj[v]:
            if to == parent[v]:
                continue
            parent[to] = v
            parent_slot[to] = slot ^ 1
            stack.append(to)

    # msg[slot] = best size of a valid subtree whose root is the source
    # of this directed slot, assuming the destination is connected to it.
    msg = [1] * (2 * max(0, N - 1))

    # Bottom-up messages: child -> parent
    for v in reversed(order[1:]):
        best1 = best2 = best3 = 0
        for to, slot in adj[v]:
            if slot == parent_slot[v]:
                continue
            x = msg[slot ^ 1]
            if x > best1:
                best1, best2, best3 = x, best1, best2
            elif x > best2:
                best2, best3 = x, best2
            elif x > best3:
                best3 = x

        if best3 > 0:
            msg[parent_slot[v]] = 1 + best1 + best2 + best3
        else:
            msg[parent_slot[v]] = 1

    answer = 0

    # Top-down rerooting: calculate every directed message.
    for v in order:
        deg = len(adj[v])
        if deg < 4:
            for _, slot in adj[v]:
                msg[slot] = 1
            continue

        values = [(msg[slot ^ 1], slot) for _, slot in adj[v]]
        values.sort(reverse=True)

        sum3 = values[0][0] + values[1][0] + values[2][0]
        sum4 = sum3 + values[3][0]

        answer = max(answer, 1 + sum4)

        for i, (x, slot) in enumerate(values):
            if i < 3:
                msg[slot] = 1 + sum4 - x
            else:
                msg[slot] = 1 + sum3

    print(answer if answer > 0 else -1)

