def solve():
    input = sys.stdin.readline
    N = int(input())
    C = [input().strip() for _ in range(N)]

    out_mask = [[0] * 26 for _ in range(N)]
    incoming = [[[] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        for j, ch in enumerate(C[i]):
            if ch != '-':
                k = ord(ch) - 97
                out_mask[i][k] |= 1 << j
                incoming[j][k].append(i)

    dist = [[-1] * N for _ in range(N)]
    visited = [0] * N
    pq = []

    for i in range(N):
        dist[i][i] = 0
        visited[i] |= 1 << i
        heapq.heappush(pq, (0, i, i))

    for i in range(N):
        for j in range(N):
            if C[i][j] != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                visited[i] |= 1 << j
                heapq.heappush(pq, (1, i, j))

    while pq:
        d, u, v = heapq.heappop(pq)
        if dist[u][v] != d:
            continue

        nd = d + 2

        for c in range(26):
            ys = out_mask[v][c]
            if ys == 0:
                continue

            for x in incoming[u][c]:
                available = ys & ~visited[x]

                while available:
                    bit = available & -available
                    y = bit.bit_length() - 1

                    visited[x] |= bit
                    dist[x][y] = nd
                    heapq.heappush(pq, (nd, x, y))

                    available -= bit

    print("\n".join(" ".join(map(str, row)) for row in dist))

