class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        total = n * m

        # Directions in clockwise order:
        # NE -> SE -> SW -> NW -> NE
        directions = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        ans = 0

        for d_idx, (dr, dc) in enumerate(directions):
            # Direction after a clockwise turn
            tdr, tdc = directions[(d_idx + 1) % 4]

            # g2[idx]: longest alternating suffix starting at idx,
            #           where current expected value is 2.
            # g0[idx]: longest alternating suffix starting at idx,
            #           where current expected value is 0.
            g2 = array('H', [0]) * total
            g0 = array('H', [0]) * total

            # Compute suffix DP in reverse of turn direction.
            if tdr == 1:
                row_order = range(n - 1, -1, -1)
            else:
                row_order = range(n)

            for i in row_order:
                base = i * m
                ni = i + tdr

                for j in range(m):
                    v = grid[i][j]
                    nj = j + tdc
                    idx = base + j

                    if 0 <= ni < n and 0 <= nj < m:
                        next_idx = ni * m + nj
                        if v == 2:
                            g2[idx] = 1 + g0[next_idx]
                        elif v == 0:
                            g0[idx] = 1 + g2[next_idx]
                    else:
                        if v == 2:
                            g2[idx] = 1
                        elif v == 0:
                            g0[idx] = 1

            # DP for the first diagonal direction.
            # prev represents the already processed previous row along dr.
            prev = [0] * m

            if dr == 1:
                first_row_order = range(n)
            else:
                first_row_order = range(n - 1, -1, -1)

            for i in first_row_order:
                cur = [0] * m

                for j in range(m):
                    v = grid[i][j]

                    if v == 1:
                        length = 1
                    else:
                        pj = j - dc
                        if 0 <= pj < m:
                            p = prev[pj]
                        else:
                            p = 0

                        if v == 2 and p > 0 and (p & 1):
                            length = p + 1
                        elif v == 0 and p > 0 and not (p & 1):
                            length = p + 1
                        else:
                            length = 0

                    cur[j] = length

                    if length > 0:
                        if length > ans:
                            ans = length

                        ni = i + tdr
                        nj = j + tdc

                        if 0 <= ni < n and 0 <= nj < m:
                            turn_idx = ni * m + nj
                            if length & 1:
                                total_length = length + g2[turn_idx]
                            else:
                                total_length = length + g0[turn_idx]

                            if total_length > ans:
                                ans = total_length

                prev = cur

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(word):
            m = len(word)
            found = [False] * (n + 1)
            if m == 0:
                return found

            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j

            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    found[i - m + 1] = True
                    j = pi[j - 1]

            return found

        def next_occurrence(found):
            inf = n + 1
            nxt = [inf] * (n + 1)
            cur = inf
            for i in range(n, -1, -1):
                if found[i]:
                    cur = i
                nxt[i] = cur
            return nxt

        la, lb, lc = len(a), len(b), len(c)

        a_found = occurrences(a) if la else None
        b_next = next_occurrence(occurrences(b)) if lb else None
        c_next = next_occurrence(occurrences(c)) if lc else None

        inf = n + 1
        answer = inf

        for start in range(n + 1):
            if la and not a_found[start]:
                continue

            pos_after_a = start + la

            if lb:
                b_start = b_next[pos_after_a]
                if b_start == inf:
                    continue
            else:
                b_start = pos_after_a

            pos_after_b = b_start + lb

            if lc:
                c_start = c_next[pos_after_b]
                if c_start == inf:
                    continue
            else:
                c_start = pos_after_b

            end = c_start + lc
            answer = min(answer, end - start)

        return -1 if answer == inf else answer

