class Solution:
    def countSubstrings(self, s: str) -> int:
        states = [[]] + [[0] * d for d in range(1, 10)]
        answer = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for d in range(1, 10):
                previous = states[d]
                current = [0] * d

                for remainder, count in enumerate(previous):
                    current[(remainder * 10 + digit) % d] += count

                current[digit % d] += 1
                states[d] = current

            if digit != 0:
                answer += states[digit][0]

        return answer

from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            need = [(target + p - 1) // p for p in points]

            # It is optimal to finish at the rightmost position
            # having the maximum required number of visits.
            mx = max(need)
            end = 0
            for i in range(n):
                if need[i] == mx:
                    end = i

            # Number of backward crossings on the current edge.
            back = need[0] - 1
            total_back = back

            for i in range(1, n - 1):
                forward_bonus = 1 if i <= end else 0
                back = max(0, need[i] - back - forward_bonus)
                total_back += back

                if 1 + end + 2 * total_back > m:
                    return False

            last_visits = back + (1 if end == n - 1 else 0)
            if last_visits < need[-1]:
                total_back += need[-1] - last_visits

            moves = 1 + end + 2 * total_back
            return moves <= m

        lo = 0
        hi = min(points) * m

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

