from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_pairs(left_choices: int, right_choices: int) -> int:
            # Count pairs (x, y) such that:
            # 1 <= x <= left_choices, 1 <= y <= right_choices
            # x + y - 1 <= k
            limit = k + 1
            max_x = min(left_choices, limit - 1)

            full_count_x = min(max_x, max(0, limit - right_choices))
            result = full_count_x * right_choices

            start = full_count_x + 1
            remaining = max_x - full_count_x
            if remaining > 0:
                result += remaining * limit - (start + max_x) * remaining // 2

            return result

        def contribution(is_maximum: bool) -> int:
            left = [-1] * n
            right = [n] * n
            stack = []

            if is_maximum:
                # Previous strictly greater element
                for i, value in enumerate(nums):
                    while stack and nums[stack[-1]] <= value:
                        stack.pop()
                    if stack:
                        left[i] = stack[-1]
                    stack.append(i)

                stack.clear()

                # Next greater or equal element
                for i in range(n - 1, -1, -1):
                    while stack and nums[stack[-1]] < nums[i]:
                        stack.pop()
                    if stack:
                        right[i] = stack[-1]
                    stack.append(i)
            else:
                # Previous strictly smaller element
                for i, value in enumerate(nums):
                    while stack and nums[stack[-1]] >= value:
                        stack.pop()
                    if stack:
                        left[i] = stack[-1]
                    stack.append(i)

                stack.clear()

                # Next smaller or equal element
                for i in range(n - 1, -1, -1):
                    while stack and nums[stack[-1]] > nums[i]:
                        stack.pop()
                    if stack:
                        right[i] = stack[-1]
                    stack.append(i)

            total = 0
            for i, value in enumerate(nums):
                left_choices = i - left[i]
                right_choices = right[i] - i
                total += value * count_pairs(left_choices, right_choices)

            return total

        return contribution(True) + contribution(False)

import sys

def main():
    N, P = map(int, sys.stdin.readline().split())
    q = N // 2
    K = N * (N - 1) // 2

    # Binomial coefficients up to N
    comb_small = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        comb_small[i][0] = 1
        comb_small[i][i] = 1
        for j in range(1, i):
            comb_small[i][j] = (comb_small[i - 1][j - 1] + comb_small[i - 1][j]) % P

    # dp[s][(last_layer_size, even_count, current_layer_parity)] = coefficients in basis (1+x)^e
    # s = number of vertices excluding vertex 1 already used
    dp = [dict() for _ in range(N)]
    dp[0][(1, 1, 0)] = [1]

    for s in range(N):
        cur = dp[s]
        if not cur:
            continue

        # Normalize all accumulated values modulo P before using them.
        for key, vec in list(cur.items()):
            cur[key] = [x % P for x in vec]

        remaining_labels = N - 1 - s

        for (a, even_count, parity), vec in cur.items():
            odd_count = s + 1 - even_count
            next_parity = parity ^ 1

            if next_parity == 0:
                max_b = min(remaining_labels, q - even_count)
            else:
                max_b = min(remaining_labels, q - odd_count)

            for b in range(1, max_b + 1):
                ns = s + b
                ne = even_count + (b if next_parity == 0 else 0)
                target_key = (b, ne, next_parity)

                # Choosing labels for the new layer
                label_ways = comb_small[remaining_labels][b]

                # Factor:
                # (1+x)^(C(b,2)) * ((1+x)^a - 1)^b
                within_shift = b * (b - 1) // 2
                needed_len = len(vec) + within_shift + a * b

                target = dp[ns].get(target_key)
                if target is None:
                    target = [0] * needed_len
                    dp[ns][target_key] = target
                elif len(target) < needed_len:
                    target.extend([0] * (needed_len - len(target)))

                for j in range(b + 1):
                    coef = (label_ways * comb_small[b][j]) % P
                    if (b - j) & 1:
                        coef = -coef

                    shift = within_shift + a * j
                    for idx, val in enumerate(vec):
                        if val:
                            target[idx + shift] += val * coef

        dp[s] = {}

    total_basis = [0] * (K + 1)

    for (a, even_count, parity), vec in dp[N - 1].items():
        if even_count != q:
            continue
        for i, v in enumerate(vec):
            total_basis[i] += v

    total_basis = [x % P for x in total_basis]

    # Factorials for binomial coefficients C(e, m)
    fact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i - 1] * i % P

    invfact = [1] * (K + 1)
    invfact[K] = pow(fact[K], P - 2, P)
    for i in range(K, 0, -1):
        invfact[i - 1] = invfact[i] * i % P

    ans = [0] * (K + 1)

    for e, coef in enumerate(total_basis):
        if coef == 0:
            continue
        for m in range(N - 1, e + 1):
            c = fact[e] * invfact[m] % P * invfact[e - m] % P
            ans[m] += coef * c

    result = [str(ans[m] % P) for m in range(N - 1, K + 1)]
    print(" ".join(result))

