from operator import mul

def matmul(a, b, mod):
    n = len(a)
    bt = list(zip(*b))
    return [
        [sum(map(mul, row, col)) % mod for col in bt]
        for row in a
    ]

def matpow(a, e, mod):
    n = len(a)
    res = None
    base = a
    while e:
        if e & 1:
            if res is None:
                res = base
            else:
                res = matmul(res, base, mod)
        e >>= 1
        if e:
            base = matmul(base, base, mod)
    if res is None:
        return [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    return res

