            return

        for L, R in intervals:
            first = L + ((1 - L) % d)
            if first <= R:
                print("No")
                return

        print("Yes")
        return

    full_mask = (1 << B) - 1
    allowed_mask = (1 << B) - (1 << (A - 1))
    mask = 1  # square 1 is reachable; bit 0 represents the latest square

    def process_good(length, mask):
        if length <= 0:
            return mask

        steps = min(length, 1000)
        for _ in range(steps):
            reachable = 1 if (mask & allowed_mask) else 0
            mask = ((mask << 1) & full_mask) | reachable

        if length > steps and mask != 0:
            mask = full_mask

        return mask

    def process_bad(length, mask):
        if length <= 0:
            return mask
        for _ in range(min(length, B)):
            mask = (mask << 1) & full_mask
        return mask

    current = 2

    for L, R in intervals:
        mask = process_good(L - current, mask)
        mask = process_bad(R - L + 1, mask)
        current = R + 1

    mask = process_good(N - current + 1, mask)

    print("Yes" if (mask & 1) else "No")

