from typing import List
from collections import Counter


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        # Maximum subarray sum without deleting anything.
        best = cur = nums[0]
        for x in nums[1:]:
            cur = max(x, cur + x)
            best = max(best, cur)

        freq = Counter(nums)

        # Deleting a non-negative value can never improve the answer.
        # Only consider negative values whose deletion leaves the array non-empty.
        candidates = {}
        for x in freq:
            if x < 0 and freq[x] < len(nums):
                candidates[x] = len(candidates)

        m = len(candidates)
        if m == 0:
            return best

        INF = 10**30
        size = 4 * m + 5

        mn = [0] * size       # minimum value in segment
        smn = [INF] * size    # second minimum value in segment
        mx = [0] * size       # maximum value in segment
        lazy_add = [0] * size

        def apply_add(node: int, value: int) -> None:
            mn[node] += value
            mx[node] += value
            if smn[node] < INF:
                smn[node] += value
            lazy_add[node] += value

        def apply_chmax(node: int, value: int) -> None:
            if mn[node] >= value:
                return
            if mx[node] == mn[node]:
                mn[node] = value
                mx[node] = value
            else:
                mn[node] = value

        def pull(node: int) -> None:
            left = node * 2
            right = left + 1

            mn[node] = min(mn[left], mn[right])
            mx[node] = max(mx[left], mx[right])

            if mn[left] < mn[right]:
                smn[node] = min(smn[left], mn[right])
            elif mn[left] > mn[right]:
                smn[node] = min(smn[right], mn[left])
            else:
                smn[node] = min(smn[left], smn[right])

        def push(node: int) -> None:
            left = node * 2
            right = left + 1

            if lazy_add[node] != 0:
                value = lazy_add[node]
                apply_add(left, value)
                apply_add(right, value)
                lazy_add[node] = 0

            floor = mn[node]
            if mn[left] < floor:
                apply_chmax(left, floor)
            if mn[right] < floor:
                apply_chmax(right, floor)

        def range_chmax(node: int, lo: int, hi: int, value: int) -> None:
            if mn[node] >= value:
                return

            if smn[node] > value:
                apply_chmax(node, value)
                return

            push(node)
            mid = (lo + hi) // 2
            range_chmax(node * 2, lo, mid, value)
            range_chmax(node * 2 + 1, mid + 1, hi, value)
            pull(node)

        def point_get(node: int, lo: int, hi: int, index: int) -> int:
            if lo == hi:
                return mn[node]

            push(node)
            mid = (lo + hi) // 2
            if index <= mid:
                return point_get(node * 2, lo, mid, index)
            return point_get(node * 2 + 1, mid + 1, hi, index)

        def point_set(node: int, lo: int, hi: int, index: int, value: int) -> None:
            if lo == hi:
                mn[node] = value
                mx[node] = value
                smn[node] = INF
                lazy_add[node] = 0
                return

            push(node)
            mid = (lo + hi) // 2
            if index <= mid:
                point_set(node * 2, lo, mid, index, value)
            else:
                point_set(node * 2 + 1, mid + 1, hi, index, value)
            pull(node)

        # For every candidate deleted value x, maintain:
        # best subarray sum ending at current position after treating x as zero.
        for value in nums:
            if value < 0 and value in candidates:
                idx = candidates[value]

                # Save this candidate's state, since this occurrence is deleted
                # and should contribute 0 rather than 'value'.
                old_state = point_get(1, 0, m - 1, idx)

                # All other candidates receive the current value.
                apply_add(1, value)
                range_chmax(1, 0, m - 1, 0)

                # Restore the deleted-value candidate state.
                point_set(1, 0, m - 1, idx, old_state)
            else:
                # This value remains for every candidate deletion.
                apply_add(1, value)
                if value < 0:
                    range_chmax(1, 0, m - 1, 0)

            best = max(best, mx[1])

        return best

