from array import array

def main():
    input = sys.stdin.buffer.readline
    K = int(input())
    S = input().strip()
    T = input().strip()

    n0 = len(S)
    m0 = len(T)

    if abs(n0 - m0) > K:
        print("No")
        return

    # Remove common prefix.
    p = 0
    limit = min(n0, m0)
    while p < limit and S[p] == T[p]:
        p += 1

    # Remove common suffix.
    q = 0
    while n0 - 1 - q >= p and m0 - 1 - q >= p and S[n0 - 1 - q] == T[m0 - 1 - q]:
        q += 1

    S = S[p:n0 - q]
    T = T[p:m0 - q]

    n = len(S)
    m = len(T)

    if abs(n - m) > K:
        print("No")
        return

    if n == 0 or m == 0:
        print("Yes" if max(n, m) <= K else "No")
        return

    MASK = (1 << 64) - 1
    BASE = 911382323

    max_len = max(n, m)

    power = array('Q', [1])
    for _ in range(max_len):
        power.append((power[-1] * BASE) & MASK)

    def build_hash(s):
        h = array('Q', [0])
        cur = 0
        for c in s:
            cur = (cur * BASE + c) & MASK
            h.append(cur)
        return h

    hs = build_hash(S)
    ht = build_hash(T)

    def get_hash(h, l, r):
        return (h[r] - (h[l] * power[r - l] & MASK)) & MASK

    def lce(x, y):
        hi = min(n - x, m - y)
        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if get_hash(hs, x, x + mid) == get_hash(ht, y, y + mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

    first = lce(0, 0)
    if first == n and first == m:
        print("Yes")
        return

    # V[diagonal] = maximum consumed length from S after exactly current edits,
    # followed by greedily matching as many equal characters as possible.
    V = {0: first}

    for _ in range(1, K + 1):
        candidates = {}

        for d, x in V.items():
            y = x - d

            # Delete one character from S.
            if x < n:
                nd = d + 1
                nx = x + 1
                if nx > candidates.get(nd, -1):
                    candidates[nd] = nx

                # Replace one character.
                if y < m:
                    nd = d
                    nx = x + 1
                    if nx > candidates.get(nd, -1):
                        candidates[nd] = nx

            # Insert one character into S (consume one from T).
            if y < m:
                nd = d - 1
                nx = x
                if nx > candidates.get(nd, -1):
                    candidates[nd] = nx

        new_v = {}

        for d, x in candidates.items():
            y = x - d
            x += lce(x, y)
            y = x - d

            if x == n and y == m:
                print("Yes")
                return

            if x > new_v.get(d, -1):
                new_v[d] = x

        V = new_v
        if not V:
            break

    print("No")

