class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def can_make(max_len: int) -> bool:
            if max_len == 1:
                flips_start_0 = 0
                flips_start_1 = 0

                for i, ch in enumerate(s):
                    expected_0 = '0' if i % 2 == 0 else '1'
                    expected_1 = '1' if i % 2 == 0 else '0'

                    if ch != expected_0:
                        flips_start_0 += 1
                    if ch != expected_1:
                        flips_start_1 += 1

                return min(flips_start_0, flips_start_1) <= numOps

            operations_needed = 0
            i = 0

            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1

                run_length = j - i
                operations_needed += run_length // (max_len + 1)

                if operations_needed > numOps:
                    return False

                i = j

            return True

        left, right = 1, n

        while left < right:
            mid = (left + right) // 2

            if can_make(mid):
                right = mid
            else:
                left = mid + 1

        return left

