                groups[r][1] += x
            else:
                groups[r] = [1, x]

        divisible_sum = 0

        for r, (cnt, sm) in groups.items():
            comp = (-r) & (m - 1)

            if r > comp:
                continue

            if r == comp:
                divisible_sum += (cnt + 1) * sm
            elif comp in groups:
                cnt2, sm2 = groups[comp]
                divisible_sum += cnt2 * sm + cnt * sm2

        total -= divisible_sum // m
        m <<= 1

    print(total)

if __name__ == "__main__":
    main()

import sys

def main():
    input = sys.stdin.buffer.readline
    n = int(input())
    a = list(map(int, input().split()))

    pref = [0] * (n + 1)
    for i, x in enumerate(a):
        pref[i + 1] = pref[i] + x

    total = pref[n]
    mx = max(a)

    size = 1
    while size < n:
        size <<= 1

    NEG = -10**30

    # For expanding left:
    # condition for index i to block is A[i] + pref[i+1] >= current_size + pref[left]
    # Store reversed so that searching nearest blocker on the left becomes first_ge.
    seg_left = [NEG] * (2 * size)
    for i in range(n):
        seg_left[size + i] = a[n - 1 - i] + pref[n - i]

    for i in range(size - 1, 0, -1):
        x = seg_left[i << 1]
        y = seg_left[i << 1 | 1]
        seg_left[i] = x if x >= y else y

    # For expanding right:
    # condition for index i to block is A[i] - pref[i] >= current_size - pref[right+1]
    seg_right = [NEG] * (2 * size)
    for i in range(n):
        seg_right[size + i] = a[i] - pref[i]

    for i in range(size - 1, 0, -1):
        x = seg_right[i << 1]
        y = seg_right[i << 1 | 1]
        seg_right[i] = x if x >= y else y

    def first_ge(seg, start, value):
        """Return smallest index >= start whose segment value is >= value, or n."""
        if start >= n:
            return n

        idx = start + size
        acc = NEG

        while True:
            while (idx & 1) == 0:
                idx >>= 1

            v = seg[idx]
            if acc >= value:
                bad = True
            elif v >= value:
                bad = True
            else:
                bad = False

            if bad:
                while idx < size:
                    idx <<= 1
                    v = seg[idx]
                    if acc >= value or v >= value:
                        pass
                    else:
                        acc = acc if acc >= v else v
                        idx += 1
                res = idx - size
                return res if res < n else n

            acc = acc if acc >= v else v
            idx += 1

            if (idx & -idx) == idx:
                break

        return n

    ans = [0] * n

    for start in range(n):
        left = start
        right = start
        cur = a[start]

        while True:
            if cur > mx:
                cur = total
                break

            old_left = left
            old_right = right

            if left > 0:
                threshold = cur + pref[left]
                # In reversed array, original indices [0, left) correspond to
                # reversed indices [n-left, n).
                pos = first_ge(seg_left, n - left, threshold)
                if pos == n:
                    new_left = 0
                else:
                    blocker = n - 1 - pos
                    new_left = blocker + 1

                if new_left != left:
                    cur += pref[left] - pref[new_left]
                    left = new_left

            if right + 1 < n:
                threshold = cur - pref[right + 1]
                blocker = first_ge(seg_right, right + 1, threshold)
                if blocker == n:
                    new_right = n - 1
                else:
                    new_right = blocker - 1

                if new_right != right:
                    cur += pref[new_right + 1] - pref[right + 1]
                    right = new_right

            if left == old_left and right == old_right:
                break

        ans[start] = cur

    print(*ans)

if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        valid = [x for x in nums if x <= threshold]
        isolated = len(nums) - len(valid)

        parent = list(range(len(valid)))
        size = [1] * len(valid)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> bool:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return False
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]
            return True

        representative = [-1] * (threshold + 1)
        components = len(valid)

        for idx, value in enumerate(valid):
            for multiple in range(value, threshold + 1, value):
                if representative[multiple] == -1:
                    representative[multiple] = idx
                elif union(idx, representative[multiple]):
                    components -= 1

        return components + isolated
